import { ref, useSyncExternalStore } from 'vue';

const counterStore = {
  value: 0,
  subscribe(callback) {
    this.callback = callback;
  },
  getSnapshot() {
    return this.value;
  }
};

export default {
  name: 'CounterDisplay',
  setup() {
    // Call useSyncExternalStore here
    const storeValue = useSyncExternalStore(
      (callback) => counterStore.subscribe(callback),
      () => counterStore.getSnapshot()
    );

    // Create increment function here
    const increment = () => {
      counterStore.value += 1;
      if (counterStore.callback) counterStore.callback();
    };

    // Return the store value
    return {
      storeValue,
      increment
    };
  }
};

<template>
  <div>
    <!-- Display storeValue here -->
    <p>Current value: {{ storeValue }}</p>
    <button @click="increment">Increment</button>
  </div>
</template>
